INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000281',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss migration and integration at B2","Use Migration vocabulary","Talk about Germany as an immigration country and integration policy"],"explanation":{"intro":"Migration and integration vocabulary covers immigration history, integration policy, and Germany''s evolving self-understanding at B2.","culturalNote":"Migration und Integration: Germany as Einwanderungsland (immigration country — long denied, now accepted): Gastarbeiter (1950s-70s — Turkish, Italian, Yugoslav — ''guest workers'' who stayed), Aussiedler (ethnic Germans from Eastern Europe post-1989), Asylsuchende (asylum seekers — 2015 peak), Fachkräftemigration (skilled worker migration). Key law: Staatsangehörigkeitsgesetz (citizenship law — 2024 reform: dual citizenship, faster naturalisation). Integration concepts: Multikulturalismus (multiculturalism), Assimilation, Leitkultur debate (dominant culture). BAMF (Bundesamt für Migration und Flüchtlinge — federal migration authority). Deutsche Islam Konferenz (German Islam Conference)."},"examples":[{"german":"Deutschland hat lange an der Vorstellung festgehalten, kein Einwanderungsland zu sein — eine Selbstdefinition, die sowohl die gesellschaftliche Realität als auch die Integrationspolitik geprägt und verzerrt hat.","english":"Germany held on for a long time to the idea of not being an immigration country — a self-definition that shaped and distorted both the social reality and integration policy."},{"german":"Erfolgreiche Integration erfordert gegenseitige Anpassungsbereitschaft: Zugewanderte müssen gesellschaftliche Grundwerte teilen, während die Aufnahmegesellschaft strukturelle Barrieren aktiv abbauen muss.","english":"Successful integration requires mutual willingness to adapt: those who have immigrated must share societal fundamental values, while the host society must actively break down structural barriers."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss migration, Germany''s integration policy, and the Einwanderungsland debate at B2."}}',
'{"items":[{"word":"festhalten an","translation":"to hold on to","pronunciation":"FEST-hahl-ten an","example":"An der Vorstellung festhalten."},{"word":"verzerren","translation":"to distort","pronunciation":"fer-TSER-en","example":"Realität verzerren."},{"word":"gegenseitig","translation":"mutual","pronunciation":"GAY-gen-zy-tikh","example":"Gegenseitige Bereitschaft."},{"word":"die Anpassungsbereitschaft","translation":"willingness to adapt","pronunciation":"dee AN-pas-oonks-beh-ryt-shaft","example":"Anpassungsbereitschaft."},{"word":"zugewandert","translation":"who have immigrated","pronunciation":"TSOO-geh-van-dert","example":"Zugewanderte."},{"word":"abbauen","translation":"to break down/eliminate","pronunciation":"AP-bow-en","example":"Barrieren abbauen."}]}',
'{"title":"An etwas festhalten — to hold on to, to cling to (a position, view, or practice)","pattern":"jemand/etwas hält an X fest = someone/something holds on to X, sticks to X (festhalten = separable: hält...fest; at + dative — maintains a position even under challenge)","explanation":"An etwas festhalten = to hold on to, to cling to, to stick with (separable: hält...fest; an + dative). Deutschland hielt an der Vorstellung fest = Germany held on to the idea. Implies persistence in the face of pressure to change. Compare: beharren auf (to insist on — more stubborn), aufrechterhalten (to maintain — more neutral), beibehalten (to retain — more practical), nicht aufgeben (to not give up — vaguer). Festhalten carries a sense of gripping something, not letting go — often used when the holding on is problematic or will eventually have to end.","examples":[{"sentence":"Er hält an seinen Überzeugungen fest, obwohl neue Fakten dagegen sprechen.","translation":"He holds on to his convictions, although new facts speak against them."},{"sentence":"Die Partei hielt an ihrer Forderung fest.","translation":"The party held on to its demand."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verzerren'' means?","options":["to distort","to skew","to warp","to misrepresent"],"correctAnswer":"to distort"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany held on for a long time to the idea of not being an immigration country — a self-definition that shaped and distorted both the social reality and integration policy.","options":["Deutschland hat lange an der Vorstellung festgehalten, kein Einwanderungsland zu sein — eine Selbstdefinition, die sowohl die gesellschaftliche Realität als auch die Integrationspolitik geprägt und verzerrt hat.","Deutschland hat sich lange nicht als Einwanderungsland verstanden.","Die Leugnung des Einwanderungslandes hat die Integrationspolitik negativ beeinflusst.","Deutschland akzeptiert erst seit kurzem seine Rolle als Einwanderungsland."],"correctAnswer":"Deutschland hat lange an der Vorstellung festgehalten, kein Einwanderungsland zu sein — eine Selbstdefinition, die sowohl die gesellschaftliche Realität als auch die Integrationspolitik geprägt und verzerrt hat."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er hält an seinen Überzeugungen fest, obwohl neue Fakten dagegen ___.","options":["sprechen","stehen","sind","zeigen"],"correctAnswer":"sprechen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The party held on to its demand","wordBankItems":["Die","Partei","hielt","an","ihrer","Forderung","fest","."],"correctAnswer":"Die Partei hielt an ihrer Forderung fest ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gegenseitig'' means?","options":["mutual","reciprocal","bilateral","shared"],"correctAnswer":"mutual"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000282',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss refugees and asylum law at B2","Use Asylrecht vocabulary","Talk about the refugee crisis and EU asylum policy"],"explanation":{"intro":"Refugees and asylum law vocabulary covers international refugee law, Germany''s asylum procedures, and 2015 refugee crisis at B2.","culturalNote":"Flüchtlinge und Asylrecht: Genfer Flüchtlingskonvention (1951 — Geneva Refugee Convention — core: non-refoulement). UNHCR. Germany: Grundgesetz Art. 16a (right to asylum — political persecution). 2015: Flüchtlingskrise/Willkommenskultur (''welcome culture'' — Merkel ''Wir schaffen das''). Dublin-Abkommen (Dublin Regulation — asylum in first EU entry country). Key statuses: Asylberechtigt (asylum-entitled), Flüchtlingsstatus (refugee status — GFK), subsidiärer Schutz (subsidiary protection). BAMF processes applications. EU: Gemeinsames Europäisches Asylsystem (CEAS), New Pact on Migration and Asylum (2024). Key tension: humanitarian obligations vs. control of migration."},"examples":[{"german":"Das Recht auf Asyl ist ein international verankertes Schutzrecht für Menschen, die vor Verfolgung fliehen müssen — kein Ermessensrecht des Aufnahmestaates, sondern eine rechtlich verbindliche Verpflichtung aus dem Völkerrecht.","english":"The right to asylum is an internationally anchored right of protection for people who must flee from persecution — not a discretionary right of the receiving state, but a legally binding obligation under international law."},{"german":"Das Prinzip des Non-Refoulement untersagt die Zurückweisung an Grenzen oder die Abschiebung in Länder, in denen Verfolgte gefoltert oder getötet werden könnten — ein absolutes Verbot, das nicht durch politischen Druck relativiert werden kann.","english":"The principle of non-refoulement prohibits the turning back at borders or the deportation to countries in which those persecuted could be tortured or killed — an absolute prohibition that cannot be relativised by political pressure."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss asylum law, non-refoulement, and Germany''s refugee policy at B2."}}',
'{"items":[{"word":"verankert","translation":"anchored/embedded","pronunciation":"fer-AN-kert","example":"International verankert."},{"word":"die Verfolgung","translation":"persecution","pronunciation":"dee fer-FOL-goong","example":"Vor Verfolgung fliehen."},{"word":"das Ermessensrecht","translation":"discretionary right","pronunciation":"dahs er-MES-ens-rekht","example":"Kein Ermessensrecht."},{"word":"verbindlich","translation":"binding","pronunciation":"fer-BIND-likh","example":"Rechtlich verbindlich."},{"word":"untersagen","translation":"to prohibit","pronunciation":"oon-ter-ZAH-gen","example":"Die Zurückweisung untersagen."},{"word":"relativieren","translation":"to relativise","pronunciation":"reh-lah-ti-VEER-en","example":"Nicht relativiert werden."}]}',
'{"title":"Nicht relativiert werden können — cannot be relativised (absolute prohibition)","pattern":"etwas kann nicht relativiert werden = something cannot be relativised, cannot be qualified away (relativieren = to relativise — to place in context in a way that weakens its absoluteness; the negation + passive asserts: it IS absolute)","explanation":"Relativieren = to relativise (to contextualise in a way that softens or qualifies something''s absolute character — e.g., ''yes, but in context it''s not so bad''). Nicht relativiert werden können = cannot be relativised = this is absolute, it admits no exception, no relativisation. Used with absolutes: Verbote (prohibitions), Grundrechte (fundamental rights), Verbrechen. Das Verbot kann nicht durch politischen Druck relativiert werden = The prohibition cannot be relativised by political pressure. Compare: nicht in Frage gestellt werden (cannot be called into question), nicht eingeschränkt werden (cannot be restricted), absolut gelten (to apply absolutely).","examples":[{"sentence":"Der Anspruch auf menschenwürdige Behandlung kann nicht relativiert werden.","translation":"The claim to dignified treatment cannot be relativised."},{"sentence":"Menschenrechtsverletzungen können nicht durch wirtschaftliche Interessen relativiert werden.","translation":"Human rights violations cannot be relativised by economic interests."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Untersagen'' means?","options":["to prohibit","to forbid","to ban","to disallow"],"correctAnswer":"to prohibit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The right to asylum is an internationally anchored right of protection for people who must flee from persecution — not a discretionary right of the receiving state, but a legally binding obligation under international law.","options":["Das Recht auf Asyl ist ein international verankertes Schutzrecht für Menschen, die vor Verfolgung fliehen müssen — kein Ermessensrecht des Aufnahmestaates, sondern eine rechtlich verbindliche Verpflichtung aus dem Völkerrecht.","Das Asylrecht schützt Verfolgte vor Abschiebung.","Asyl ist ein Menschenrecht, kein Gefallen des Staates.","Das Asylrecht verpflichtet Staaten, Flüchtlinge aufzunehmen."],"correctAnswer":"Das Recht auf Asyl ist ein international verankertes Schutzrecht für Menschen, die vor Verfolgung fliehen müssen — kein Ermessensrecht des Aufnahmestaates, sondern eine rechtlich verbindliche Verpflichtung aus dem Völkerrecht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Anspruch auf menschenwürdige Behandlung kann nicht ___.","options":["relativiert werden","in Frage gestellt werden","aufgehoben werden","eingeschränkt werden"],"correctAnswer":"relativiert werden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Human rights violations cannot be relativised by economic interests","wordBankItems":["Menschenrechtsverletzungen","können","nicht","durch","wirtschaftliche","Interessen","relativiert","werden","."],"correctAnswer":"Menschenrechtsverletzungen können nicht durch wirtschaftliche Interessen relativiert werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verbindlich'' means?","options":["binding","obligatory","mandatory","compulsory"],"correctAnswer":"binding"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000283',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss interculturality at B2","Use Interkulturalität vocabulary","Talk about intercultural dialogue and cultural competence"],"explanation":{"intro":"Interculturality vocabulary covers cultural difference, intercultural dialogue, and competence at B2.","culturalNote":"Interkulturalität: Key concepts: Kultur (culture — not static, contested — Kulturalist vs. constructivist approaches), Kulturrelativismus (cultural relativism — no universal standards), Universalismus (universal human rights), Stereotyp (stereotype), Vorurteil (prejudice). Intercultural dialogue: EU concept (Interreligiöser Dialog, Goethe-Institut). Germany: Islam Konferenz, Jugendmigrationsdienste. Key thinkers: Edward Said (Orientalism — Othering), Homi Bhabha (Third Space — hybridity), Amartya Sen (Identity and Violence — multiple identities). Key challenge: Othering (reducing people to one identity), Essentialism (treating culture as fixed)."},"examples":[{"german":"Interkulturelle Kompetenz bedeutet nicht, andere Kulturen durch ein Raster von Nationalstereotypen zu betrachten, sondern das Bewusstsein zu schärfen, dass Kulturen intern divers, historisch gewachsen und ständig im Wandel sind.","english":"Intercultural competence does not mean viewing other cultures through a grid of national stereotypes, but sharpening the awareness that cultures are internally diverse, historically grown, and constantly in change."},{"german":"Die Unterscheidung zwischen kulturellen Praktiken, die als Ausdruck von Differenz respektiert werden, und solchen, die universale Menschenrechte verletzen, gehört zu den schwierigsten Grenzziehungsaufgaben interkultureller Ethik.","english":"The distinction between cultural practices that are respected as an expression of difference and those that violate universal human rights belongs to the most difficult boundary-drawing tasks of intercultural ethics."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss intercultural competence, cultural relativism, and Othering at B2."}}',
'{"items":[{"word":"das Raster","translation":"grid/framework","pronunciation":"dahs RAS-ter","example":"Durch ein Raster betrachten."},{"word":"schärfen","translation":"to sharpen","pronunciation":"SHÄR-fen","example":"Bewusstsein schärfen."},{"word":"intern divers","translation":"internally diverse","pronunciation":"in-TERN di-VERS","example":"Intern divers sein."},{"word":"die Grenzziehung","translation":"boundary-drawing","pronunciation":"dee GRENTS-tsee-oong","example":"Grenzziehungsaufgaben."},{"word":"die Differenz","translation":"difference","pronunciation":"dee di-feh-RETS","example":"Ausdruck von Differenz."},{"word":"zugehören","translation":"to belong to","pronunciation":"TSOO-geh-hö-ren","example":"Zu den schwierigsten gehören."}]}',
'{"title":"Zu etwas gehören — to belong to, to be among, to be part of","pattern":"etwas gehört zu X = something belongs to X, is one of X, forms part of X (zu + dative; can describe category membership, group belonging, or topical association)","explanation":"Zu X gehören = to belong to X, to be among X, to be part of X. Etwas gehört zu den schwierigsten Aufgaben = something belongs to/is among the most difficult tasks (category membership: it IS one of those things). Different uses: 1) category: die Frage gehört zu den schwierigsten = the question is among the most difficult; 2) group: Er gehört zur Partei = he belongs to the party; 3) required for: Geduld gehört dazu = patience is part of it. Compare: zählen zu (to count among — more selective), gehören zu (broader — membership or required element), dazugehören (to belong — social/contextual belonging).","examples":[{"sentence":"Diese Frage gehört zu den am meisten diskutierten.","translation":"This question is among the most discussed."},{"sentence":"Vertrauen gehört zu jeder guten Zusammenarbeit.","translation":"Trust belongs to/is part of every good collaboration."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Raster'' means?","options":["grid/framework","template","scheme","pattern"],"correctAnswer":"grid/framework"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Intercultural competence does not mean viewing other cultures through a grid of national stereotypes, but sharpening the awareness that cultures are internally diverse, historically grown, and constantly in change.","options":["Interkulturelle Kompetenz bedeutet nicht, andere Kulturen durch ein Raster von Nationalstereotypen zu betrachten, sondern das Bewusstsein zu schärfen, dass Kulturen intern divers, historisch gewachsen und ständig im Wandel sind.","Interkulturelle Kompetenz bedeutet, andere Kulturen zu verstehen.","Man darf Kulturen nicht stereotypisieren, sondern muss sie als komplex betrachten.","Interkulturelle Kompetenz erfordert, Kulturen als dynamisch und vielschichtig zu sehen."],"correctAnswer":"Interkulturelle Kompetenz bedeutet nicht, andere Kulturen durch ein Raster von Nationalstereotypen zu betrachten, sondern das Bewusstsein zu schärfen, dass Kulturen intern divers, historisch gewachsen und ständig im Wandel sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Frage gehört zu den am meisten ___.","options":["diskutierten","debattierten","umstrittenen","besprochenen"],"correctAnswer":"diskutierten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust belongs to every good collaboration","wordBankItems":["Vertrauen","gehört","zu","jeder","guten","Zusammenarbeit","."],"correctAnswer":"Vertrauen gehört zu jeder guten Zusammenarbeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Grenzziehung'' means?","options":["boundary-drawing","line-drawing","delimitation","demarcation"],"correctAnswer":"boundary-drawing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000284',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss racism and discrimination at B2","Use Rassismus vocabulary","Talk about structural racism, antidiscrimination law, and Germany''s history"],"explanation":{"intro":"Racism and discrimination vocabulary covers structural racism, Germany''s colonial history, and antidiscrimination law at B2.","culturalNote":"Rassismus und Diskriminierung: Germany: Nationalsozialismus legacy (Holocaust — fundamental obligation). Struktureller Rassismus (structural racism — systemic disadvantage — not only individual prejudice). Kolonialgeschichte (colonial history — Namibia genocide, 2021 recognition). NSU-Komplex (far-right neo-Nazi cell 2000-2011 — 10 murders, institutional failure). AGG (Allgemeines Gleichbehandlungsgesetz — General Equal Treatment Act — prohibits discrimination). Antidiskriminierungsstelle (Federal Antidiscrimination Agency). Key movements: Black Lives Matter (Germany), Initiative Schwarze Menschen in Deutschland (ISD), Beratungsstellen für Betroffene rassistischer Diskriminierung. Key concept: Othering, rassistisches Profiling (racial profiling)."},"examples":[{"german":"Rassismus beschränkt sich nicht auf individuelle Vorurteile, sondern umfasst auch strukturelle Dimensionen: Institutionen, Gesetze und gesellschaftliche Normen können systematisch Benachteiligung reproduzieren, auch ohne bewusste diskriminatorische Absicht einzelner Akteure.","english":"Racism is not limited to individual prejudices, but also encompasses structural dimensions: institutions, laws, and social norms can systematically reproduce disadvantage, even without the conscious discriminatory intent of individual actors."},{"german":"Deutschlands Auseinandersetzung mit seiner NS-Vergangenheit ist — trotz aller Verdienste — noch unabgeschlossen hinsichtlich des kolonialen Erbes und der strukturellen Diskriminierung, die Schwarze Menschen und People of Color in Deutschland noch heute erleben.","english":"Germany''s engagement with its National Socialist past is — despite all its merits — still unfinished with regard to the colonial legacy and the structural discrimination that Black people and People of Colour in Germany still experience today."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss structural racism, Germany''s colonial history, and antidiscrimination law at B2."}}',
'{"items":[{"word":"sich beschränken auf","translation":"to be limited to","pronunciation":"zikh beh-SHRÄN-ken owf","example":"Sich nicht beschränken auf."},{"word":"umfassen","translation":"to encompass/include","pronunciation":"OOM-fas-en","example":"Strukturelle Dimensionen umfassen."},{"word":"reproduzieren","translation":"to reproduce","pronunciation":"reh-pro-doo-TSEER-en","example":"Benachteiligung reproduzieren."},{"word":"die Absicht","translation":"intent","pronunciation":"dee AP-zikht","example":"Diskriminatorische Absicht."},{"word":"das Verdienst","translation":"merit/credit","pronunciation":"dahs fer-DEENST","example":"Trotz aller Verdienste."},{"word":"unabgeschlossen","translation":"unfinished","pronunciation":"oon-AP-geh-shlos-en","example":"Noch unabgeschlossen."}]}',
'{"title":"Trotz + genitive — despite (concessive preposition)","pattern":"trotz + genitive = despite (concessive — the main clause happens DESPITE the content of the trotz-phrase; always genitive except in informal speech where dative is increasingly heard)","explanation":"Trotz + genitive = despite. Trotz aller Verdienste (= trotz + genitive of alle Verdienste — all their merits) = despite all merits. Genitive: trotz des Problems (despite the problem), trotz aller Bemühungen (despite all efforts), trotz seiner Erfahrung (despite his experience). Note: In informal spoken German, trotz + dative is common: trotz dem Problem — but in formal writing, genitive is correct. Compare: obwohl (although — full subordinate clause), obgleich (although — more literary), ungeachtet (regardless of — more formal), zum Trotz (in defiance of — adversarial connotation).","examples":[{"sentence":"Trotz großer Hindernisse hat sie ihr Ziel erreicht.","translation":"Despite great obstacles, she achieved her goal."},{"sentence":"Trotz intensiver Forschung sind viele Fragen offen.","translation":"Despite intensive research, many questions remain open."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Umfassen'' means?","options":["to encompass/include","to comprise","to cover","to contain"],"correctAnswer":"to encompass/include"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Racism is not limited to individual prejudices, but also encompasses structural dimensions: institutions, laws, and social norms can systematically reproduce disadvantage, even without the conscious discriminatory intent of individual actors.","options":["Rassismus beschränkt sich nicht auf individuelle Vorurteile, sondern umfasst auch strukturelle Dimensionen: Institutionen, Gesetze und gesellschaftliche Normen können systematisch Benachteiligung reproduzieren, auch ohne bewusste diskriminatorische Absicht einzelner Akteure.","Rassismus ist nicht nur persönlich, sondern auch systemisch.","Struktureller Rassismus bedeutet, dass Systeme Benachteiligung erzeugen, nicht nur Individuen.","Auch unbewusste Vorurteile können diskriminierend wirken."],"correctAnswer":"Rassismus beschränkt sich nicht auf individuelle Vorurteile, sondern umfasst auch strukturelle Dimensionen: Institutionen, Gesetze und gesellschaftliche Normen können systematisch Benachteiligung reproduzieren, auch ohne bewusste diskriminatorische Absicht einzelner Akteure."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Trotz großer Hindernisse hat sie ihr Ziel ___.","options":["erreicht","erzielt","geschafft","verwirklicht"],"correctAnswer":"erreicht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Despite intensive research many questions remain open","wordBankItems":["Trotz","intensiver","Forschung","sind","viele","Fragen","offen","."],"correctAnswer":"Trotz intensiver Forschung sind viele Fragen offen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unabgeschlossen'' means?","options":["unfinished","incomplete","ongoing","open"],"correctAnswer":"unfinished"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000285',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss nationalism and populism at B2","Use Nationalismus vocabulary","Talk about the rise of populism in Europe and Germany"],"explanation":{"intro":"Nationalism and populism vocabulary covers right-wing populism, AfD, and the causes of nationalist movements at B2.","culturalNote":"Nationalismus und Populismus: Populism = people vs. elite rhetoric (Cas Mudde definition: thin ideology). Right-wing populism: AfD (Alternative für Deutschland — founded 2013, right-wing populist to far-right — Verfassungsschutz observed some parts). FPÖ (Austria), Le Pen (France), Orbán (Hungary). Causes: perceived identity loss, economic anxiety, distrust in elites. Key terms: Abgehängte (left-behind), Systemparteien (establishment parties), Lügenpresse (lying press — pejorative label for mainstream media). Germany: Basic Law protects democracy — Parteiverbot (party ban, Art. 21 GG). Wehrhafte Demokratie (militant/resilient democracy). Historical echo: Weimar Republic''s failure."},"examples":[{"german":"Populismus lässt sich als eine dünne Ideologie beschreiben, die gesellschaftliche Konflikte auf eine binäre Opposition zwischen dem ''reinen Volk'' und einer ''korrupten Elite'' reduziert — eine Vereinfachung, die komplexe politische Realitäten verzerrt.","english":"Populism can be described as a thin ideology that reduces social conflicts to a binary opposition between the ''pure people'' and a ''corrupt elite'' — a simplification that distorts complex political realities."},{"german":"Der Aufstieg rechtspopulistischer Parteien in Europa lässt sich nicht monokausal erklären: Ökonomische Abstiegsängste, Identitätspolitik, Misstrauen in Institutionen und gezielte Desinformation wirken zusammen.","english":"The rise of right-wing populist parties in Europe cannot be explained monocausally: economic fears of decline, identity politics, distrust in institutions, and targeted disinformation interact."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss populism, AfD, and the causes of right-wing movements in Germany and Europe at B2."}}',
'{"items":[{"word":"binär","translation":"binary","pronunciation":"bi-NÄR","example":"Binäre Opposition."},{"word":"monokausal","translation":"monocausal","pronunciation":"mo-no-kow-ZAH-leh","example":"Monokausal erklären."},{"word":"die Abstiegsangst","translation":"fear of decline","pronunciation":"dee AP-shteeks-angst","example":"Ökonomische Abstiegsängste."},{"word":"das Misstrauen","translation":"distrust","pronunciation":"dahs MIS-trow-en","example":"Misstrauen in Institutionen."},{"word":"zusammenwirken","translation":"to interact","pronunciation":"tsoo-ZA-men-vir-ken","example":"Faktoren wirken zusammen."},{"word":"die Vereinfachung","translation":"simplification","pronunciation":"dee fer-YN-fa-khoong","example":"Eine Vereinfachung."}]}',
'{"title":"Sich als X beschreiben lassen — can be described as X (lassen + reflexive = allowed/possible)","pattern":"etwas lässt sich als X beschreiben = something can be described as X (lassen + reflexive + infinitive = passive-like possibility: it allows itself to be described as X)","explanation":"Lassen + sich + infinitive = passive-like possibility (not reflexive reflexive — this is the lassen of permission/possibility). Etwas lässt sich als X beschreiben = something can be described as X, it is possible to describe it as X. Populismus lässt sich als dünne Ideologie beschreiben = Populism can be described as a thin ideology. Note: lassen + sich can also express: 1) allowing something (er lässt sich nicht stören — he lets himself not be disturbed), 2) possibility (this use — something is describable/treatable as X). Compare: kann als X bezeichnet werden (can be referred to as X), gilt als X (is regarded as X), kann beschrieben werden als X (full passive — slightly more awkward).","examples":[{"sentence":"Das Phänomen lässt sich schwer in eine Kategorie einordnen.","translation":"The phenomenon is difficult to place in a single category."},{"sentence":"Die Methode lässt sich auf viele Bereiche anwenden.","translation":"The method can be applied to many areas."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Monokausal'' means?","options":["monocausal","single-cause","one-dimensional","simplistic"],"correctAnswer":"monocausal"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Populism can be described as a thin ideology that reduces social conflicts to a binary opposition between the ''pure people'' and a ''corrupt elite'' — a simplification that distorts complex political realities.","options":["Populismus lässt sich als eine dünne Ideologie beschreiben, die gesellschaftliche Konflikte auf eine binäre Opposition zwischen dem ''reinen Volk'' und einer ''korrupten Elite'' reduziert — eine Vereinfachung, die komplexe politische Realitäten verzerrt.","Populismus vereinfacht politische Realität auf einen Konflikt zwischen Volk und Elit.","Populisten stellen sich als Vertreter des einfachen Volkes gegen die Eliten dar.","Populismus teilt die Gesellschaft in gutes Volk und böse Eliten."],"correctAnswer":"Populismus lässt sich als eine dünne Ideologie beschreiben, die gesellschaftliche Konflikte auf eine binäre Opposition zwischen dem ''reinen Volk'' und einer ''korrupten Elite'' reduziert — eine Vereinfachung, die komplexe politische Realitäten verzerrt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Phänomen lässt sich schwer in eine Kategorie ___.","options":["einordnen","einstufen","einteilen","eingliedern"],"correctAnswer":"einordnen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The method can be applied to many areas","wordBankItems":["Die","Methode","lässt","sich","auf","viele","Bereiche","anwenden","."],"correctAnswer":"Die Methode lässt sich auf viele Bereiche anwenden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Vereinfachung'' means?","options":["simplification","reduction","oversimplification","abridgment"],"correctAnswer":"simplification"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000286',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss civil society at B2","Use Zivilgesellschaft vocabulary","Talk about NGOs, volunteering, and democratic participation"],"explanation":{"intro":"Civil society vocabulary covers civic engagement, NGOs, volunteering, and Germany''s strong civil society tradition at B2.","culturalNote":"Zivilgesellschaft: Germany has a rich civil society tradition (Vereine — clubs/associations: 600,000+ registered, ~25M members). Key institutions: Wohlfahrtsverbände (welfare associations — AWO, Caritas, Diakonie, Rotes Kreuz), political foundations (Stiftungen — Friedrich Ebert, Konrad Adenauer, Heinrich Böll — funded by state). Ehrenamt (honorary/voluntary office — civic tradition). NGOs: Amnesty International, Greenpeace Germany. Lobbyismus debate (lobbying regulation). Gemeinnützigkeit (public benefit status — tax advantages). Key democratic function: intermediate space between state and individual (Tocqueville). Digital civil society (Petitionen, Online-Aktivismus)."},"examples":[{"german":"Die Zivilgesellschaft bildet ein intermediäres Handlungsfeld zwischen Markt, Staat und Privathaushalt: Sie aggregiert gesellschaftliche Interessen, bietet Räume demokratischer Aushandlung und erzeugt soziales Kapital.","english":"Civil society forms an intermediary field of action between market, state, and private household: it aggregates societal interests, offers spaces for democratic negotiation, and generates social capital."},{"german":"Das Ehrenamt ist in Deutschland tief in der gesellschaftlichen Kultur verwurzelt — eine Infrastruktur der freiwilligen Mitgestaltung, die staatliche Strukturen nicht ersetzen, aber sinnvoll ergänzen kann.","english":"Voluntary civic service is deeply rooted in German societal culture — an infrastructure of voluntary co-shaping that cannot replace state structures, but can meaningfully supplement them."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss civil society, Ehrenamt, and democratic participation in Germany at B2."}}',
'{"items":[{"word":"intermediär","translation":"intermediary","pronunciation":"in-ter-meh-DYÄR","example":"Intermediäres Handlungsfeld."},{"word":"aggregieren","translation":"to aggregate","pronunciation":"ag-reh-GEER-en","example":"Interessen aggregieren."},{"word":"aushandeln","translation":"to negotiate","pronunciation":"OWS-han-deln","example":"Demokratisch aushandeln."},{"word":"das Ehrenamt","translation":"voluntary civic service","pronunciation":"dahs EH-ren-amt","example":"Im Ehrenamt tätig."},{"word":"verwurzelt","translation":"rooted","pronunciation":"fer-VOOORT-selt","example":"Tief verwurzelt."},{"word":"ergänzen","translation":"to supplement","pronunciation":"er-GÄN-tsen","example":"Sinnvoll ergänzen."}]}',
'{"title":"In der Gesellschaft/Kultur verwurzelt sein — to be rooted in society/culture","pattern":"etwas ist (tief) in X verwurzelt = something is (deeply) rooted in X (verwurzelt = past participle as adjective — rooted; in + dative — where the roots are)","explanation":"In X verwurzelt sein = to be rooted in X (verwurzelt = rooted, embedded — past participle of verwurzeln). Das Ehrenamt ist tief in der gesellschaftlichen Kultur verwurzelt = Voluntary service is deeply rooted in German societal culture. Combines with: tief (deeply), fest (firmly), kulturell (culturally), historisch (historically). A metaphor: roots going deep into culture, history, practice. Compare: in etwas verankert sein (to be anchored in — more institutional/legal), fest etabliert sein (to be firmly established), tief in etwas eingebettet sein (to be deeply embedded in — more neutral).","examples":[{"sentence":"Diese Tradition ist tief in der lokalen Kultur verwurzelt.","translation":"This tradition is deeply rooted in local culture."},{"sentence":"Das Vertrauen in Institutionen ist historisch tief verwurzelt.","translation":"Trust in institutions is historically deeply rooted."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Aggregieren'' means?","options":["to aggregate","to collect","to accumulate","to gather"],"correctAnswer":"to aggregate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Civil society forms an intermediary field of action between market, state, and private household: it aggregates societal interests, offers spaces for democratic negotiation, and generates social capital.","options":["Die Zivilgesellschaft bildet ein intermediäres Handlungsfeld zwischen Markt, Staat und Privathaushalt: Sie aggregiert gesellschaftliche Interessen, bietet Räume demokratischer Aushandlung und erzeugt soziales Kapital.","Zivilgesellschaft ist der Raum zwischen Staat und Bürger.","NGOs und Vereine vertreten Interessen und fördern demokratische Teilhabe.","Zivilgesellschaft ergänzt staatliche Strukturen durch bürgerschaftliches Engagement."],"correctAnswer":"Die Zivilgesellschaft bildet ein intermediäres Handlungsfeld zwischen Markt, Staat und Privathaushalt: Sie aggregiert gesellschaftliche Interessen, bietet Räume demokratischer Aushandlung und erzeugt soziales Kapital."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Tradition ist tief in der lokalen Kultur ___.","options":["verwurzelt","verankert","eingebettet","verwurzelt"],"correctAnswer":"verwurzelt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust in institutions is historically deeply rooted","wordBankItems":["Das","Vertrauen","in","Institutionen","ist","historisch","tief","verwurzelt","."],"correctAnswer":"Das Vertrauen in Institutionen ist historisch tief verwurzelt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ergänzen'' means?","options":["to supplement","to complement","to complete","to add to"],"correctAnswer":"to supplement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000287',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social movements at B2","Use Soziale Bewegungen vocabulary","Talk about protest, political change, and Germany''s movement history"],"explanation":{"intro":"Social movements vocabulary covers collective action, protest theory, and major social movements in Germany at B2.","culturalNote":"Soziale Bewegungen: Key German movements: Friedensbewegung (peace movement — 1980s, against nuclear weapons), Frauenbewegung (women''s movement), Anti-Atomkraft-Bewegung (anti-nuclear — Wyhl, Brokdorf, Gorleben — influenced Energiewende), Montagsdemonstrationen (Monday demonstrations — Leipzig 1989 — peaceful revolution — DDR). More recent: Fridays for Future (Klimabewegung — Greta Thunberg, Germany leading), Black Lives Matter. Theory: Resource Mobilisation Theory (McCarthy/Zald), Political Process Model, Framing (collective action frames — Goffman). Key tactics: Ziviler Ungehorsam (civil disobedience — Thoreau/Gandhi/King), Sit-ins, Blockaden."},"examples":[{"german":"Soziale Bewegungen entstehen, wenn gesellschaftliche Gruppen kollektiv Missstände thematisieren und außerinstitutionellen Druck auf Entscheidungsträger ausüben — ein Mechanismus, der im Laufe der Geschichte wiederholt politischen Wandel angetrieben hat.","english":"Social movements arise when societal groups collectively place grievances on the agenda and exert extra-institutional pressure on decision-makers — a mechanism that has repeatedly driven political change throughout history."},{"german":"Die Montagsdemonstrationen in Leipzig 1989 demonstrieren die transformative Kraft gewaltfreier kollektiver Aktion: In wenigen Wochen veränderten sie die politische Grundkonstellation eines ganzen Landes.","english":"The Monday demonstrations in Leipzig in 1989 demonstrate the transformative power of non-violent collective action: within a few weeks, they changed the basic political configuration of an entire country."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss social movements, Leipzig 1989, and the theory of collective action at B2."}}',
'{"items":[{"word":"thematisieren","translation":"to place on the agenda","pronunciation":"teh-mah-ti-ZEER-en","example":"Missstände thematisieren."},{"word":"außerinstitutionell","translation":"extra-institutional","pronunciation":"OW-ser-in-sti-too-TSYO-nel","example":"Außerinstitutioneller Druck."},{"word":"ausüben","translation":"to exert","pronunciation":"OWS-ü-ben","example":"Druck ausüben."},{"word":"antreiben","translation":"to drive/propel","pronunciation":"AN-try-ben","example":"Wandel antreiben."},{"word":"die Grundkonstellation","translation":"basic configuration","pronunciation":"dee GROONT-kon-stel-ah-TSYOHN","example":"Politische Grundkonstellation."},{"word":"gewaltfrei","translation":"non-violent","pronunciation":"geh-VALT-fry","example":"Gewaltfreie Aktion."}]}',
'{"title":"Im Laufe + genitive — in the course of (temporal phrase)","pattern":"im Laufe + genitive = in the course of (fixed phrase: im Laufe + genitive noun — time period during which something happens repeatedly or progressively)","explanation":"Im Laufe + genitive = in the course of (im Laufe = in the course, as time passes). Im Laufe der Geschichte = in the course of history. Im Laufe der Zeit (in the course of time — very common), im Laufe des Jahres (in the course of the year). Often with wiederholt (repeatedly), zunehmend (increasingly), allmählich (gradually) — showing progressive change over a time span. Compare: während (during — simpler), über die Zeit (over time — more colloquial), mit der Zeit (over time — process), historically: im Verlauf (in the course of — more formal/neutral synonym).","examples":[{"sentence":"Im Laufe der Zeit hat sie an Selbstvertrauen gewonnen.","translation":"In the course of time, she gained in self-confidence."},{"sentence":"Im Laufe des Gesprächs wurde mir klar, was gemeint war.","translation":"In the course of the conversation, it became clear to me what was meant."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gewaltfrei'' means?","options":["non-violent","peaceful","passive","unarmed"],"correctAnswer":"non-violent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Social movements arise when societal groups collectively place grievances on the agenda and exert extra-institutional pressure on decision-makers — a mechanism that has repeatedly driven political change throughout history.","options":["Soziale Bewegungen entstehen, wenn gesellschaftliche Gruppen kollektiv Missstände thematisieren und außerinstitutionellen Druck auf Entscheidungsträger ausüben — ein Mechanismus, der im Laufe der Geschichte wiederholt politischen Wandel angetrieben hat.","Soziale Bewegungen üben Druck auf Politiker aus, um Veränderungen zu erreichen.","Wenn Gruppen kollektiv handeln, können sie politische Veränderungen bewirken.","Proteste und Bewegungen sind wichtige Instrumente des politischen Wandels."],"correctAnswer":"Soziale Bewegungen entstehen, wenn gesellschaftliche Gruppen kollektiv Missstände thematisieren und außerinstitutionellen Druck auf Entscheidungsträger ausüben — ein Mechanismus, der im Laufe der Geschichte wiederholt politischen Wandel angetrieben hat."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Laufe der Zeit hat sie an Selbstvertrauen ___.","options":["gewonnen","zugelegt","gewachsen","erlangt"],"correctAnswer":"gewonnen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In the course of the conversation it became clear to me what was meant","wordBankItems":["Im","Laufe","des","Gesprächs","wurde","mir","klar",",","was","gemeint","war","."],"correctAnswer":"Im Laufe des Gesprächs wurde mir klar , was gemeint war ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Antreiben'' means?","options":["to drive/propel","to push","to motivate","to spur"],"correctAnswer":"to drive/propel"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000288',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss gender and society at B2","Use Gender vocabulary","Talk about gender equality, feminism, and Germany''s progress and challenges"],"explanation":{"intro":"Gender and society vocabulary covers gender equality policy, feminist theory, and Germany''s gender pay gap at B2.","culturalNote":"Gender und Gesellschaft: Germany: Gleichstellungsgesetz (equality law), Parité-Debatte (gender parity in politics — Verfassungsgerichtsentscheidungen blocking mandatory parity in Bundestag). Gender Pay Gap: 18% (2023 — above EU average). Elterngeld (parental benefit — shared between parents). Quoten (quotas — corporate boards: 30% women in supervisory boards since 2016). Feministische Theorie: Simone de Beauvoir (''man ist nicht als Frau geboren, wird es''), Judith Butler (Performativität des Geschlechts — gender as performance). Diversität (diversity — non-binary, LGBTQ). Drittes Geschlecht (third gender — introduced 2018 in Germany). #MeToo in Germany."},"examples":[{"german":"Geschlechtergleichstellung ist in Deutschland rechtlich weit fortgeschritten, aber die Realität hinkt dem normativen Anspruch hinterher: Lohnlücke, ungleiche Care-Arbeit und Unterrepräsentation in Führungspositionen zeigen, dass strukturelle Barrieren fortbestehen.","english":"Gender equality in Germany has progressed far legally, but reality lags behind the normative claim: the pay gap, unequal care work, and under-representation in leadership positions show that structural barriers persist."},{"german":"Gender als soziale Konstruktion zu verstehen bedeutet nicht, biologische Unterschiede zu leugnen, sondern die gesellschaftlichen Mechanismen zu analysieren, durch die bestimmte Attribute als ''typisch männlich'' oder ''typisch weiblich'' normiert werden.","english":"Understanding gender as a social construction does not mean denying biological differences, but analysing the social mechanisms through which certain attributes are normalised as ''typically male'' or ''typically female''."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss gender equality, the gender pay gap, and gender as social construction at B2."}}',
'{"items":[{"word":"hinterherhinken","translation":"to lag behind","pronunciation":"HIN-ter-her-hing-ken","example":"Dem Anspruch hinterherhinken."},{"word":"fortbestehen","translation":"to persist","pronunciation":"FORT-beh-shte-en","example":"Barrieren fortbestehen."},{"word":"leugnen","translation":"to deny","pronunciation":"LOYG-nen","example":"Unterschiede nicht leugnen."},{"word":"normieren","translation":"to normalise","pronunciation":"nor-MEER-en","example":"Attribute normieren."},{"word":"die Unterrepräsentation","translation":"under-representation","pronunciation":"dee oon-ter-reh-prä-zen-tah-TSYOHN","example":"Unterrepräsentation in Führung."},{"word":"das Konstrukt","translation":"construct","pronunciation":"dahs kon-STROOKT","example":"Soziales Konstrukt."}]}',
'{"title":"Dem Anspruch hinterherhinken — to lag behind the claim/standard","pattern":"etwas hinkt X hinterher = something lags behind X (hinterherhinken = separable: hinkt...hinterher; dative of what it trails; metaphor from limping)","explanation":"Hinterherhinken + dative = to lag behind (hinterher + hinken = to limp behind). Die Realität hinkt dem normativen Anspruch hinterher = Reality lags behind the normative claim. Metaphor: limping (hinken) behind — trailing, not catching up. Always separable: hinkt...hinterher (present), hinkte hinterher (simple past). Compare: hinter X zurückbleiben (to remain behind X — more neutral), hinter X zurückfallen (to fall behind X — more dynamic), auf dem Rückstand sein gegenüber X (to be behind X — more bureaucratic). Hinterherhinken often implies the gap is persistent and problematic.","examples":[{"sentence":"Die Praxis hinkt der Theorie oft hinterher.","translation":"Practice often lags behind theory."},{"sentence":"Die Digitalisierung hinkt in Deutschland internationalen Standards hinterher.","translation":"Digitalisation in Germany lags behind international standards."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Fortbestehen'' means?","options":["to persist","to continue","to remain","to endure"],"correctAnswer":"to persist"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gender equality in Germany has progressed far legally, but reality lags behind the normative claim: the pay gap, unequal care work, and under-representation in leadership positions show that structural barriers persist.","options":["Geschlechtergleichstellung ist in Deutschland rechtlich weit fortgeschritten, aber die Realität hinkt dem normativen Anspruch hinterher: Lohnlücke, ungleiche Care-Arbeit und Unterrepräsentation in Führungspositionen zeigen, dass strukturelle Barrieren fortbestehen.","Rechtlich gibt es Gleichstellung, aber in der Praxis bestehen Ungleichheiten fort.","Obwohl Deutschland Gleichstellungsgesetze hat, ist die Lohnlücke noch immer groß.","Frauen sind formal gleichgestellt, aber strukturelle Benachteiligung bleibt."],"correctAnswer":"Geschlechtergleichstellung ist in Deutschland rechtlich weit fortgeschritten, aber die Realität hinkt dem normativen Anspruch hinterher: Lohnlücke, ungleiche Care-Arbeit und Unterrepräsentation in Führungspositionen zeigen, dass strukturelle Barrieren fortbestehen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Praxis hinkt der Theorie oft ___.","options":["hinterher","nach","hinterher","hinten"],"correctAnswer":"hinterher"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Digitalisation in Germany lags behind international standards","wordBankItems":["Die","Digitalisierung","hinkt","in","Deutschland","internationalen","Standards","hinterher","."],"correctAnswer":"Die Digitalisierung hinkt in Deutschland internationalen Standards hinterher ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Normieren'' means?","options":["to normalise","to standardise","to regulate","to define as normal"],"correctAnswer":"to normalise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000289',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss demographic change at B2","Use Demographischer Wandel vocabulary","Talk about ageing society, birth rates, and immigration needs"],"explanation":{"intro":"Demographic change vocabulary covers Germany''s ageing population, birth rate decline, and policy responses at B2.","culturalNote":"Demographischer Wandel: Germany has one of oldest populations globally. Key data: Geburtenrate (birth rate — ~1.5 children per woman, below replacement rate 2.1), Lebenserwartung (life expectancy — rising), Median Alter (median age — rising). Rentenprobleme (pension issues — fewer contributors, more recipients). Fachkräftemangel (skilled worker shortage — partly from demographics). Key policies: Elterngeld (parental benefit — 2007 — designed to encourage births), Kita-Ausbau (childcare expansion), Migration als Ausgleich (migration as compensation). Key concepts: Altersstruktur (age structure), Altersquotient (old-age dependency ratio), Bevölkerungspyramide (population pyramid). Key challenge: Renten, Pflege, Fachkräfte."},"examples":[{"german":"Der demographische Wandel stellt die Sozialsysteme vor eine doppelte Herausforderung: Schrumpfende Erwerbsbevölkerung und wachsende Rentenempfängerzahl belasten die Beitragssysteme, während gleichzeitig der Pflegebedarf steigt.","english":"Demographic change poses a twofold challenge to the social systems: a shrinking working-age population and growing number of pension recipients burden the contribution systems, while at the same time care needs are rising."},{"german":"Migration ist kein Allheilmittel gegen den demographischen Wandel, kann aber — bei gelingender Integration — den Fachkräftemangel mildern und die Beitragsbasis der Sozialsysteme stützen.","english":"Migration is not a panacea for demographic change, but can — with successful integration — alleviate the skilled worker shortage and support the contribution base of the social systems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s demographic change, pension challenges, and migration''s role at B2."}}',
'{"items":[{"word":"schrumpfend","translation":"shrinking","pronunciation":"SHROOMPF-end","example":"Schrumpfende Erwerbsbevölkerung."},{"word":"die Erwerbsbevölkerung","translation":"working-age population","pronunciation":"dee er-VERBS-beh-völ-ker-oong","example":"Erwerbsbevölkerung."},{"word":"mildern","translation":"to alleviate","pronunciation":"MIL-dern","example":"Fachkräftemangel mildern."},{"word":"stützen","translation":"to support/prop up","pronunciation":"SHTÜ-tsen","example":"Beitragsbasis stützen."},{"word":"das Allheilmittel","translation":"panacea","pronunciation":"dahs AL-hyl-mi-tel","example":"Kein Allheilmittel."},{"word":"gelingend","translation":"successful","pronunciation":"geh-LING-end","example":"Gelingende Integration."}]}',
'{"title":"Kein Allheilmittel sein, aber... — not a panacea, but... (qualified concession)","pattern":"X ist kein Allheilmittel gegen Y, kann aber Z = X is not a panacea for Y, but can Z (Allheilmittel = panacea — fixed idiom: all-healing-remedy; kein Allheilmittel sein = to not solve everything)","explanation":"Kein Allheilmittel sein = to not be a panacea (Allheilmittel = panacea, all-healing remedy). Used to reject an oversimplified solution while acknowledging real but limited benefits: ''X cannot solve everything, but does help with Y.'' Very common in policy discourse to acknowledge limitations while maintaining a qualified positive argument. Fixed idiomatic expression. Compare: keine Wunderlösung sein (no miracle solution), nicht ausreichen (not sufficient), nicht alles lösen (not solve everything).","examples":[{"sentence":"Technologie ist kein Allheilmittel für gesellschaftliche Probleme, kann sie aber unterstützen.","translation":"Technology is not a panacea for social problems, but can support their resolution."},{"sentence":"Mehr Kontrolle ist kein Allheilmittel, wenn die Grundursachen ungelöst bleiben.","translation":"More control is not a panacea when the root causes remain unresolved."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schrumpfend'' means?","options":["shrinking","declining","diminishing","contracting"],"correctAnswer":"shrinking"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Demographic change poses a twofold challenge to the social systems: a shrinking working-age population and growing number of pension recipients burden the contribution systems, while at the same time care needs are rising.","options":["Der demographische Wandel stellt die Sozialsysteme vor eine doppelte Herausforderung: Schrumpfende Erwerbsbevölkerung und wachsende Rentenempfängerzahl belasten die Beitragssysteme, während gleichzeitig der Pflegebedarf steigt.","Die alternde Gesellschaft belastet Renten- und Pflegesystem gleichermaßen.","Weniger Beitragszahler und mehr Rentner machen das Sozialsystem unter Druck.","Demographischer Wandel bedeutet mehr Kosten für Renten und Pflege."],"correctAnswer":"Der demographische Wandel stellt die Sozialsysteme vor eine doppelte Herausforderung: Schrumpfende Erwerbsbevölkerung und wachsende Rentenempfängerzahl belasten die Beitragssysteme, während gleichzeitig der Pflegebedarf steigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Technologie ist kein Allheilmittel für gesellschaftliche Probleme, kann sie aber ___.","options":["unterstützen","lösen","mildern","verbessern"],"correctAnswer":"unterstützen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: More control is not a panacea when the root causes remain unresolved","wordBankItems":["Mehr","Kontrolle","ist","kein","Allheilmittel",",","wenn","die","Grundursachen","ungelöst","bleiben","."],"correctAnswer":"Mehr Kontrolle ist kein Allheilmittel , wenn die Grundursachen ungelöst bleiben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Mildern'' means?","options":["to alleviate","to mitigate","to ease","to reduce"],"correctAnswer":"to alleviate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000028a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urbanisation at B2","Use Urbanisierung vocabulary","Talk about urban growth, housing, and smart cities"],"explanation":{"intro":"Urbanisation vocabulary covers urban growth, housing crises, and smart city development at B2.","culturalNote":"Urbanisierung: Germany: 75%+ urban. Key cities: Berlin (capital, 3.6M), Hamburg (1.8M), Munich (1.5M). Wohnungskrise (housing crisis — especially Berlin, Munich: rents doubled since 2010 — Mietpreisbremse — rent brake — insufficient). Gentrifizierung (gentrification — displacement of lower-income residents). Smart City initiatives (digital urban governance). Suburbanisierung (suburbanisation). Strukturschwache Regionen (structurally weak regions — rural East Germany, Ruhr). Key tension: Verdichtung vs. Stadtlandschaft (density vs. green space). Deutsche Städte: Stadtrechte (city rights historically), Stadtstaaten (Berlin, Hamburg, Bremen as Länder). Stadtplanung (urban planning — Bebauungsplan, Flächennutzungsplan)."},"examples":[{"german":"Die zunehmende Konzentration von Bevölkerung, Wirtschaft und Infrastruktur in urbanen Zentren verschärft regionale Ungleichgewichte: Metropolregionen boomen, während ländliche Räume unter Bevölkerungsrückgang, Infrastrukturabbau und Wirtschaftsschwäche leiden.","english":"The increasing concentration of population, economy, and infrastructure in urban centres sharpens regional imbalances: metropolitan regions are booming, while rural areas suffer from population decline, infrastructure dismantlement, and economic weakness."},{"german":"Wohnraummangel in deutschen Großstädten ist das Ergebnis jahrzehntelanger Unterinvestition in den sozialen Wohnungsbau — ein Problem, das Regulierungsinstrumente wie die Mietpreisbremse allein nicht lösen können.","english":"The shortage of housing in German cities is the result of decades of underinvestment in social housing — a problem that regulatory instruments such as the rent brake alone cannot solve."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss urbanisation, Germany''s housing crisis, and regional imbalances at B2."}}',
'{"items":[{"word":"verschärfen","translation":"to sharpen/worsen","pronunciation":"fer-SHÄR-fen","example":"Ungleichgewichte verschärfen."},{"word":"das Ungleichgewicht","translation":"imbalance","pronunciation":"dahs oon-GLYKH-geh-vikt","example":"Regionale Ungleichgewichte."},{"word":"der Bevölkerungsrückgang","translation":"population decline","pronunciation":"dayr beh-VÖL-ker-oonks-rük-gang","example":"Bevölkerungsrückgang."},{"word":"der Infrastrukturabbau","translation":"infrastructure dismantlement","pronunciation":"dayr in-fra-shtrook-TOOR-ap-bow","example":"Infrastrukturabbau."},{"word":"jahrzehntelang","translation":"for decades","pronunciation":"YAHR-tsen-teh-lang","example":"Jahrzehntelange Unterinvestition."},{"word":"der Wohnungsbau","translation":"housing construction","pronunciation":"dayr VOH-noonks-bow","example":"Sozialer Wohnungsbau."}]}',
'{"title":"Das Ergebnis + genitive sein — to be the result of (genitive construction identifying cause)","pattern":"etwas ist das Ergebnis + genitive = something is the result of something (Ergebnis = result; genitive of what caused it: das Ergebnis jahrzehntelanger Unterinvestition = the result of decades of underinvestment)","explanation":"Das Ergebnis + genitive = the result of. Wohnraummangel ist das Ergebnis jahrzehntelanger Unterinvestition = Housing shortage is the result of decades of underinvestment. Genitive after das Ergebnis: Ergebnis + genitive of the cause. Compare: ist auf X zurückzuführen (is attributable to X — more causal analysis), liegt an X (is due to X — more colloquial), geht auf X zurück (goes back to X — historical origin), folgt aus X (follows from X — logical consequence).","examples":[{"sentence":"Die Krise ist das Ergebnis langjähriger Versäumnisse.","translation":"The crisis is the result of years of failures."},{"sentence":"Vertrauen ist das Ergebnis konsequenter Verlässlichkeit.","translation":"Trust is the result of consistent reliability."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verschärfen'' means?","options":["to sharpen/worsen","to intensify","to aggravate","to heighten"],"correctAnswer":"to sharpen/worsen"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The shortage of housing in German cities is the result of decades of underinvestment in social housing — a problem that regulatory instruments such as the rent brake alone cannot solve.","options":["Wohnraummangel in deutschen Großstädten ist das Ergebnis jahrzehntelanger Unterinvestition in den sozialen Wohnungsbau — ein Problem, das Regulierungsinstrumente wie die Mietpreisbremse allein nicht lösen können.","Die Wohnungsnot in deutschen Städten hat strukturelle Ursachen.","Eine Mietpreisbremse allein reicht nicht, um die Wohnungsnot zu lösen.","Jahrelanger Verzicht auf Sozialwohnungsbau hat die Wohnungskrise verursacht."],"correctAnswer":"Wohnraummangel in deutschen Großstädten ist das Ergebnis jahrzehntelanger Unterinvestition in den sozialen Wohnungsbau — ein Problem, das Regulierungsinstrumente wie die Mietpreisbremse allein nicht lösen können."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Krise ist das Ergebnis langjähriger ___.","options":["Versäumnisse","Fehler","Probleme","Schwächen"],"correctAnswer":"Versäumnisse"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust is the result of consistent reliability","wordBankItems":["Vertrauen","ist","das","Ergebnis","konsequenter","Verlässlichkeit","."],"correctAnswer":"Vertrauen ist das Ergebnis konsequenter Verlässlichkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Jahrzehntelang'' means?","options":["for decades","over decades","decade-long","multidecade"],"correctAnswer":"for decades"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

